import * as T from './timer'
import type { LogEntry, Phase, Settings, TimerState } from './timer'

const SETTINGS_KEY = 'pomodoro.settings'
const LOG_KEY = 'pomodoro.log'

function load<V>(key: string, sanitize: (raw: unknown) => V): V {
